cd /app/output/vite-react && cat > src/index.css << 'EOF'
@import "tailwindcss";

@theme {
  --color-orchard-dark: #1d1d1f;
  --color-orchard-gray: #6e6e73;
  --color-orchard-light: #f5f5f7;
  --color-orchard-blue: #0066cc;
  --color-orchard-blue-hover: #0077ed;
  --font-sans: "SF Pro Display", -apple-system, BlinkMacSystemFont, "Helvetica Neue", "Segoe UI", sans-serif;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  color: #1d1d1f;
  background: #ffffff;
}

/* Carousel */
.carousel-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  padding: 0 20px;
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.carousel-track::-webkit-scrollbar {
  display: none;
}
.carousel-card {
  flex: 0 0 auto;
  scroll-snap-align: start;
}

/* Product card hover */
.product-card {
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}
.product-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 24px rgba(0,0,0,0.08);
}

/* Tab underline animation */
.tab-btn {
  position: relative;
}
.tab-btn::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0%;
  height: 2px;
  background: #1d1d1f;
  transition: width 0.25s ease;
}
.tab-btn.active::after {
  width: 100%;
}

/* Footer accordion */
.footer-section-title {
  cursor: pointer;
}
.footer-links {
  overflow: hidden;
  transition: max-height 0.3s ease;
}
@media (max-width: 768px) {
  .footer-links {
    max-height: 0;
  }
  .footer-links.open {
    max-height: 400px;
  }
}
@media (min-width: 769px) {
  .footer-links {
    max-height: none !important;
  }
}
EOF
